import {searchPages,snippet} from './search.js';
const $ = id=>document.getElementById(id);
const query=$('query'), issue=$('issue'), mode=$('mode'), sort=$('sort'), results=$('results');
const format = date=>new Date(date+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});
let archive, matches=[], limit=20;
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
function viewer(page){const params=new URLSearchParams({issue:page.date,page:String(page.page||1)});if(query.value.trim())params.set('q',query.value.trim());return 'reader.html?'+params;}
function highlight(text,terms){const frag=document.createDocumentFragment();const escaped=terms.filter(Boolean).sort((a,b)=>b.length-a.length).map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));if(!escaped.length){frag.append(text);return frag;}const re=new RegExp('('+escaped.join('|')+')','gi');let last=0;for(const m of text.matchAll(re)){frag.append(text.slice(last,m.index));frag.append(node('mark',m[0]));last=m.index+m[0].length;}frag.append(text.slice(last));return frag;}
function browse(){results.replaceChildren();const grid=node('div',undefined,'issue-grid');const issues=archive.issues.filter(x=>!issue.value||x.date===issue.value).slice().reverse();for(const item of issues){const a=node('a',undefined,'issue-card');a.href=viewer(item);a.append(node('div','Piedmont Post','paper-symbol'),node('div','WEEKLY EDITION','eyebrow'),node('h3',format(item.date)),node('p',item.pages+' pages'),node('span','Read this issue ↗','open-issue'));grid.append(a);}results.append(grid);$('results-title').textContent='Browse the latest issues';$('status').textContent=issues.length+' issues available';$('more').hidden=true;}
function draw(){results.replaceChildren();for(const match of matches.slice(0,limit)){const card=node('article',undefined,'result');const date=node('div',format(match.date),'result-date');date.append(node('small','Page '+match.page));if(match.title && match.titleSource==='detected')date.append(node('small','Detected headline'));const body=node('div');const title=node('h3');const a=node('a');a.append(highlight(match.title || 'Page '+match.page+' · Piedmont Post',match.terms));a.href=viewer(match);title.append(a);const excerpt=node('p');excerpt.append(highlight(snippet(match.excerptText || match.text,match.terms),match.terms));body.append(title,excerpt);const open=node('a','Open page '+match.page+' ↗','page-link');open.href=viewer(match);card.append(date,body,open);results.append(card);}if(!matches.length){const empty=node('div',undefined,'empty');empty.append(node('h3','No matching pages'),node('p','Try fewer words, a different spelling, or search across all issues.'));results.append(empty);}$('results-title').textContent='Results for “'+query.value.trim()+'”';$('status').textContent=matches.length+' matching '+(matches.length===1?'page':'pages');$('more').hidden=limit>=matches.length;}
function run(){if(!archive)return;const params=new URLSearchParams();for(const [key,el]of Object.entries({q:query,issue,mode,sort}))if(el.value)params.set(key,el.value);history.replaceState(null,'','?'+params);if(!query.value.trim()){browse();return;}matches=searchPages(archive.pages,query.value,{issue:issue.value,mode:mode.value,sort:sort.value});limit=20;draw();}
$('search-form').addEventListener('submit',e=>{e.preventDefault();run();});for(const el of [issue,mode,sort])el.addEventListener('change',run);query.addEventListener('search',run);document.querySelectorAll('[data-query]').forEach(b=>b.addEventListener('click',()=>{query.value=b.dataset.query;run();}));$('more').addEventListener('click',()=>{limit+=20;draw();});
try {const response=await fetch('search-index.json');if(!response.ok)throw Error('Unable to load index');archive=await response.json();for(const item of archive.issues.slice().reverse()){const opt=node('option',format(item.date));opt.value=item.date;issue.append(opt);}const params=new URLSearchParams(location.search);for(const [key,el]of Object.entries({q:query,issue,mode,sort}))if(params.has(key))el.value=params.get(key);run();}catch(error){$('status').textContent='Archive unavailable';results.append(node('p','Could not load the archive. Please reload the page. For local preview, serve this folder over HTTP.'));console.error(error);}
